export type BarChartAnimationProps = Record<string, any>;

// --- Component ---

const BarChartAnimation: React.FC<BarChartAnimationProps> = ({
  backgroundColor = "#000000",
  cardBackgroundColor = "#0f1115",
  transparentBackground = false,
  titleColor = "#ffffff",
  textColor = "#a1a1aa",
  pinkColor = "#f40f5a",
  yellowColor = "#ffc40d",
  purpleColor = "#4f0dc4",
  title = "Bar chart",
  description = "Minim dolor in amet nulla laboris enim dolore consequatt...",
  percentage = "+86%",
  durationInSeconds = 8,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle background transparency
  const bg = transparentBackground ? "transparent" : backgroundColor;

  // Animation Utilities
  const entranceSpring = spring({
    frame,
    fps,
    config: { damping: 20, stiffness: 100 },
  });

  const textOpacity = interpolate(frame, [10, 30], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const textTranslateY = interpolate(frame, [10, 30], [20, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Data structure matching the image visually
  // Values are percentages of the max height available for bars
  const barData = useMemo(() => [
    { purple: 40, yellow: 20, pink: 20 }, // Bar 1
    { purple: 20, yellow: 40, pink: 15 }, // Bar 2
    { purple: 25, yellow: 25, pink: 15 }, // Bar 3
    { purple: 35, yellow: 15, pink: 10 }, // Bar 4
    { purple: 15, yellow: 15, pink: 25 }, // Bar 5
    { purple: 20, yellow: 15, pink: 10 }, // Bar 6
    { purple: 15, yellow: 10, pink: 15 }, // Bar 7
    { purple: 10, yellow: 10, pink: 45 }, // Bar 8 (Huge pink top)
  ], []);

  const totalBars = barData.length;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bg,
        fontFamily: "Inter",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Card Container */}
      <div
        style={{
          width: 500,
          height: 500,
          backgroundColor: cardBackgroundColor,
          borderRadius: 32,
          padding: 40,
          display: "flex",
          flexDirection: "column",
          boxShadow: "0px 20px 50px rgba(0,0,0,0.5)",
          transform: `scale(${entranceSpring})`,
          opacity: Math.min(1, entranceSpring),
        }}
      >
        {/* Header Row */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
          }}
        >
          {/* Left: Icon + Title */}
          <div style={{ display: "flex", alignItems: "center", gap: 16 }}>
            <div style={{ transform: "scale(1.2)" }}>
              <ChartIcon color={titleColor} />
            </div>
            <h1
              style={{
                color: titleColor,
                fontSize: 32,
                fontWeight: 700,
                margin: 0,
                letterSpacing: "-0.5px",
              }}
            >
              {title}
            </h1>
          </div>

          {/* Right: Trend + Percentage */}
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ transform: "translateY(2px)" }}>
              <SquigglyIcon color={yellowColor} />
            </div>
            <span
              style={{
                color: titleColor,
                fontSize: 24,
                fontWeight: 600,
              }}
            >
              {percentage}
            </span>
          </div>
        </div>

        {/* Description Text */}
        <div
            style={{
                marginTop: 20,
                opacity: textOpacity,
                transform: `translateY(${textTranslateY}px)`,
            }}
        >
            <p
                style={{
                    color: textColor,
                    fontSize: 20,
                    lineHeight: 1.4,
                    margin: 0,
                    fontWeight: 400,
                }}
            >
                {description}
            </p>
        </div>

        {/* Chart Area */}
        <div
          style={{
            flex: 1,
            display: "flex",
            alignItems: "flex-end",
            justifyContent: "space-between",
            marginTop: 40,
          }}
        >
          {barData.map((bar, index) => {
            // Stagger animations
            const delay = index * 3;
            const startFrame = 20 + delay;

            // Spring config for height growth
            const grow = spring({
              frame: frame - startFrame,
              fps,
              config: { damping: 15, stiffness: 120, mass: 0.8 },
            });

            // Calculate total relative height to scale the bar properly within the container
            // The max height sum in our data is roughly 80-90. Let's assume max possible is 100.
            const totalVal = bar.purple + bar.yellow + bar.pink;
            
            return (
              <div
                key={index}
                style={{
                  width: "10%",
                  height: "100%", // The bar container takes full height, but we align items to bottom
                  display: "flex",
                  flexDirection: "column",
                  justifyContent: "flex-end",
                }}
              >
                {/* The actual stacked bar */}
                <div
                  style={{
                    width: "100%",
                    borderRadius: 10,
                    overflow: "hidden", // Ensures segments don't overflow rounded corners
                    // Scale vertical from bottom
                    height: `${totalVal}%`, 
                    display: "flex",
                    flexDirection: "column-reverse", // Stack from bottom up
                    transform: `scaleY(${grow})`,
                    transformOrigin: "bottom",
                  }}
                >
                  {/* Bottom Segment (Purple) */}
                  <div
                    style={{
                      width: "100%",
                      height: `${(bar.purple / totalVal) * 100}%`,
                      backgroundColor: purpleColor,
                    }}
                  />
                  {/* Middle Segment (Yellow) */}
                  <div
                    style={{
                      width: "100%",
                      height: `${(bar.yellow / totalVal) * 100}%`,
                      backgroundColor: yellowColor,
                    }}
                  />
                  {/* Top Segment (Pink) */}
                  <div
                    style={{
                      width: "100%",
                      height: `${(bar.pink / totalVal) * 100}%`,
                      backgroundColor: pinkColor,
                    }}
                  />
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

